<script setup lang="ts">
/**
 * Disclosure list (`design/components/accordion.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/accordion.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import {
  computed,
  onBeforeUnmount,
  onMounted,
  ref,
  useId,
  useTemplateRef,
  watch,
  type VNode,
} from 'vue'

import * as zag from '@zag-js/accordion'
import { normalizeProps, useMachine } from '@zag-js/vue'

import { Icon, agentMember, useDirection } from '@polymorph/vue'
import { useKeyedPresence } from '@polymorph/vue/motion'
import styles from '@polymorph/recipes/structure/accordion.module.css'

export type AccordionHeadingLevel = NonNullable<AccordionProps['headingLevel']>

export interface AccordionItem {
  value: string
  label: string
  content: VNode | string
  disabled?: boolean
}

export interface AccordionProps {
  /**
   * The open item may be closed again, leaving the list shut.
   */
  collapsible?: boolean
  defaultValue?: string | string[]
  headingLevel?: 3 | 4
  items: AccordionItem[]
  type?: 'single' | 'multiple'
  value?: string | string[]
}

defineOptions({ name: 'Accordion', inheritAttrs: false })

const props = withDefaults(defineProps<AccordionProps>(), {
  collapsible: undefined,
  headingLevel: 3,
  type: 'single',
})
const emit = defineEmits<{ valueChange: [value: string | string[]] }>()
const uid = useId()
const heights = ref(new Map())
const regions = useTemplateRef<HTMLElement[]>('regions')
const root = useTemplateRef<HTMLElement>('root')
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    multiple: props.type === 'multiple',
    collapsible: props.type === 'multiple' || (props.collapsible ?? true),
    value:
      props.value === undefined
        ? undefined
        : Array.isArray(props.value)
          ? props.value
          : props.value === ''
            ? []
            : [props.value],
    defaultValue:
      props.defaultValue === undefined
        ? undefined
        : Array.isArray(props.defaultValue)
          ? props.defaultValue
          : [props.defaultValue],
    onValueChange: (details) => {
      emit('valueChange', props.type === 'multiple' ? details.value : (details.value[0] ?? ''))
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const regionPresent = useKeyedPresence(
  () => api.value.value,
  regions,
  (element) =>
    props.items.find(
      (item) => api.value.getItemContentProps({ value: item.value }).id === element.id,
    )?.value,
)
const effect1 = () => {
  heights.value = new Map(
    (regions.value ?? []).map((region) => [region.id, region.scrollHeight + 'px']),
  )
}
onMounted(effect1)
watch(() => api.value.value, effect1, { flush: 'post' })
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'Accordion',
    element: () => root.value,
    state: () => ({
      value: api.value.value,
      items: props.items.map((item) => ({
        id: item.value,
        label: item.label,
        ...(item.disabled === true ? { disabled: true } : {}),
      })),
    }),
    actions: {
      expand: {
        argument: 'id',
        run: (value) =>
          api.value.value.includes(value) ||
          api.value.setValue(props.type === 'multiple' ? [...api.value.value, value] : [value]),
      },
      collapse: {
        argument: 'id',
        run: (value) =>
          (() => {
            if (!api.value.value.includes(value)) return
            if (props.type !== 'multiple' && !(props.collapsible ?? true)) {
              throw new Error('This accordion keeps one item open; expand another item instead.')
            }
            api.value.setValue(api.value.value.filter((shown) => shown !== value))
          })(),
      },
    },
  })
  release2 = () => {
    ran()
  }
}
onMounted(effect2)
onBeforeUnmount(() => release2?.())
</script>

<template>
  <div ref="root" v-bind="api.getRootProps()" :class="styles.root" data-member="accordion">
    <template v-for="item in items" :key="item.value">
      <!-- item -->
      <div
        v-bind="api.getItemProps({ value: item.value, disabled: item.disabled })"
        :class="styles.item"
      >
        <component :is="headingLevel === 4 ? 'h4' : 'h3'" :class="styles.header">
          <!-- trigger -->
          <button
            v-bind="api.getItemTriggerProps({ value: item.value, disabled: item.disabled })"
            :class="styles.trigger"
            data-accordion-part="trigger"
          >
            <span :class="styles.label">
              {{ item.label }}
            </span>
            <span :class="styles.chevron">
              <Icon name="down" />
            </span>
          </button>
        </component>
        <!-- region -->
        <div
          ref="regions"
          v-bind="api.getItemContentProps({ value: item.value, disabled: item.disabled })"
          :class="styles.content"
          :style="{
            '--radix-accordion-content-height': heights.get(
              api.getItemContentProps({ value: item.value, disabled: item.disabled }).id,
            ),
          }"
          :hidden="!regionPresent.has(item.value)"
          data-accordion-part="region"
        >
          <div :class="styles.inner">
            <template v-if="typeof item.content === 'string'">{{ item.content }}</template>
            <template v-else>
              <component :is="item.content" />
            </template>
          </div>
        </div>
      </div>
    </template>
  </div>
</template>
